using System;
using System.Collections.Generic;
using UnityEngine;

namespace Operation1989.AI.Drone
{
    /// <summary>
    /// Smooth 3D aerial locomotion controller for the Tactical Drone.
    /// Traverses waypoints generated by A* search, rotates rotors, tilts/banks into turns,
    /// performs forward whisker obstacle detection for dynamic re-planning, and handles hover physics.
    /// </summary>
    [DisallowMultipleComponent]
    [RequireComponent(typeof(TacticalDroneNavigationGraph))]
    public class TacticalDroneMovement : MonoBehaviour
    {
        [Header("Flight Dynamics")]
        [Range(2f, 25f)] [SerializeField] private float cruiseSpeed = 8.0f;
        [Range(20f, 180f)] [SerializeField] private float turnSpeed = 90.0f;
        [Range(5f, 45f)] [SerializeField] private float maxBankAngle = 25.0f;
        [Range(0.2f, 3f)] [SerializeField] private float waypointArrivalDistance = 1.2f;

        [Header("Hover Bobbing")]
        [SerializeField] private bool enableHoverBobbing = true;
        [SerializeField] private float bobbingAmplitude = 0.25f;
        [SerializeField] private float bobbingSpeed = 1.8f;

        [Header("Visual Components")]
        [SerializeField] private Transform[] rotorBlades;
        [Range(300f, 3000f)] [SerializeField] private float rotorSpinSpeed = 1800f;

        [Header("Obstacle Avoidance Whisker")]
        [SerializeField] private float whiskerDistance = 6.0f;
        [SerializeField] private LayerMask obstacleLayers = 1 << 0;

        public event Action OnDynamicObstacleDetected;

        public bool IsMoving { get; private set; }
        public float CurrentSpeed => currentVelocity.magnitude;
        public Vector3 Velocity => currentVelocity;

        private TacticalDroneNavigationGraph navGraph;
        private DroneDamage damageHandler;
        private List<Vector3> activePath = new List<Vector3>();
        private int currentPathIndex = 0;
        private Vector3 currentVelocity = Vector3.zero;
        private float hoverTimer = 0f;
        private float currentBankAngle = 0f;

        private void Awake()
        {
            navGraph = GetComponent<TacticalDroneNavigationGraph>();
            damageHandler = GetComponent<DroneDamage>();
        }

        public void SetPath(List<Vector3> path)
        {
            activePath = path != null ? new List<Vector3>(path) : new List<Vector3>();
            currentPathIndex = 0;
            IsMoving = activePath.Count > 0;
        }

        public void ClearPath()
        {
            activePath.Clear();
            currentPathIndex = 0;
            IsMoving = false;
        }

        private void Update()
        {
            if (damageHandler && damageHandler.Destroyed)
            {
                IsMoving = false;
                return; // Let physics take over on wreck
            }

            SpinRotors();
            TraverseActivePath();
            ApplyHoverBobbing();
        }

        private void SpinRotors()
        {
            if (rotorBlades == null || rotorBlades.Length == 0) return;
            float rot = rotorSpinSpeed * Time.deltaTime;
            for (int i = 0; i < rotorBlades.Length; i++)
            {
                if (rotorBlades[i])
                {
                    // Alternate spin directions for realism
                    float dir = (i % 2 == 0) ? 1f : -1f;
                    rotorBlades[i].Rotate(Vector3.up, rot * dir, Space.Self);
                }
            }
        }

        private void TraverseActivePath()
        {
            if (!IsMoving || activePath.Count == 0 || currentPathIndex >= activePath.Count)
            {
                IsMoving = false;
                currentVelocity = Vector3.Lerp(currentVelocity, Vector3.zero, Time.deltaTime * 3f);
                return;
            }

            Vector3 targetPoint = activePath[currentPathIndex];
            Vector3 delta = targetPoint - transform.position;
            float dist = delta.magnitude;

            // Forward whisker collision check to detect dynamic obstacles and trigger re-planning
            if (dist > 1.0f && Physics.SphereCast(transform.position, 0.8f, delta.normalized, out RaycastHit hit, whiskerDistance, obstacleLayers, QueryTriggerInteraction.Ignore))
            {
                // Dynamic obstacle in forward path!
                Debug.LogWarning($"[Drone Movement] Dynamic obstacle detected ({hit.collider.name})! Triggering A* re-plan.");
                OnDynamicObstacleDetected?.Invoke();
                return;
            }

            if (dist <= waypointArrivalDistance)
            {
                currentPathIndex++;
                if (currentPathIndex >= activePath.Count)
                {
                    IsMoving = false;
                    return;
                }
                targetPoint = activePath[currentPathIndex];
                delta = targetPoint - transform.position;
            }

            Vector3 targetDir = delta.normalized;
            Vector3 desiredVelocity = targetDir * cruiseSpeed;
            currentVelocity = Vector3.MoveTowards(currentVelocity, desiredVelocity, cruiseSpeed * 2f * Time.deltaTime);
            transform.position += currentVelocity * Time.deltaTime;

            // Smooth rotation towards target direction
            if (targetDir.sqrMagnitude > 0.001f)
            {
                Quaternion targetRot = Quaternion.LookRotation(targetDir, Vector3.up);
                transform.rotation = Quaternion.RotateTowards(transform.rotation, targetRot, turnSpeed * Time.deltaTime);

                // Compute banking angle into turn (roll)
                float angleDelta = Vector3.SignedAngle(transform.forward, targetDir, Vector3.up);
                float desiredBank = Mathf.Clamp(-angleDelta * 0.8f, -maxBankAngle, maxBankAngle);
                currentBankAngle = Mathf.Lerp(currentBankAngle, desiredBank, Time.deltaTime * 5f);
                transform.rotation *= Quaternion.Euler(0, 0, currentBankAngle);
            }
        }

        private void ApplyHoverBobbing()
        {
            if (!enableHoverBobbing || IsMoving) return;
            hoverTimer += Time.deltaTime * bobbingSpeed;
            float bobOffset = Mathf.Sin(hoverTimer) * bobbingAmplitude * Time.deltaTime;
            transform.position += new Vector3(0, bobOffset, 0);
        }

        private void OnDrawGizmosSelected()
        {
            // Draw forward obstacle whisker
            Gizmos.color = Color.magenta;
            Gizmos.DrawRay(transform.position, transform.forward * whiskerDistance);
            Gizmos.DrawWireSphere(transform.position + transform.forward * whiskerDistance, 0.8f);
        }
    }
}
